# 特征编码：独热编码 / 按用户选择顺序进行标签编码
import io
import re
import pandas as pd


def _to_frame(value):
    if isinstance(value, pd.DataFrame):
        return value.copy()
    if isinstance(value, bytes):
        for encoding in ('utf-8-sig', 'utf-8', 'gbk', 'gb18030'):
            try:
                return pd.read_csv(io.StringIO(value.decode(encoding)))
            except UnicodeDecodeError:
                continue
        raise RuntimeError('CSV 编码无法识别')
    if isinstance(value, str):
        return pd.read_csv(io.StringIO(value.lstrip('\ufeff')))
    raise RuntimeError('输入 data 必须是 CSV 文本或 DataFrame')


def _display(value):
    if pd.isna(value):
        return None
    text = str(value)
    return text if text.strip() else None


def _unique_name(base, used):
    name = base
    number = 2
    while name in used:
        name = base + '_' + str(number)
        number += 1
    used.add(name)
    return name


_df = _to_frame(data).reset_index(drop=True)
if _df.empty:
    raise RuntimeError('原始表是空的，没有行可编码')
_column = {{column}}
_method = {{method}}
_order = {{label_order}}
if not isinstance(_column, str) or not _column:
    raise RuntimeError('请先选择编码列')
if _column not in [str(item) for item in _df.columns]:
    raise RuntimeError('编码列「' + str(_column) + '」不在原始表中')
if _method not in ('独热编码', '标签编码'):
    raise RuntimeError('编码方式必须是“独热编码”或“标签编码”')

_position = list(_df.columns).index(_column)
_series = _df[_column]
_values = []
for _value in _series.tolist():
    _text = _display(_value)
    if _text is not None and _text not in _values:
        _values.append(_text)
_base = _df.drop(columns=[_column]).copy()

if _method == '标签编码':
    if not isinstance(_order, list) or not _order:
        raise RuntimeError('标签编码需要按顺序勾选类别：第 1 个 = 0，第 2 个 = 1，以此类推')
    _order = [str(item) for item in _order]
    if len(set(_order)) != len(_order):
        raise RuntimeError('标签顺序中不能有重复类别')
    _unknown = [item for item in _order if item not in _values]
    if _unknown:
        raise RuntimeError('标签顺序包含原表中不存在的类别：' + '、'.join(_unknown))
    _missing = [item for item in _values if item not in _order]
    if _missing:
        raise RuntimeError('这些类别还没有选择编码顺序：' + '、'.join(_missing))
    _mapping = {item: index for index, item in enumerate(_order)}
    _encoded = _series.map(lambda value: pd.NA if _display(value) is None else _mapping[_display(value)]).astype('Int64')
    _base.insert(_position, _column, _encoded)
    print('标签编码完成：' + '，'.join(str(index) + '=' + item for index, item in enumerate(_order)))
else:
    _used = set(str(item) for item in _base.columns)
    _encoded_columns = []
    for _value in _values:
        _safe = re.sub(r'\s+', '_', _value.strip()) or '空'
        _name = _unique_name(_column + '_' + _safe, _used)
        _encoded_columns.append((_name, (_series.map(_display) == _value).astype(int)))
    for _offset, (_name, _encoded) in enumerate(_encoded_columns):
        _base.insert(_position + _offset, _name, _encoded)
    print('独热编码完成：原列「' + _column + '」已替换为 ' + str(len(_encoded_columns)) + ' 个 0/1 列')

return {'data': _base}
